	JsonArray compactDraw(List<CompactLayout.Cell> cells)
	{
		JsonArray draw = new JsonArray();
		for (CompactLayout.Cell cell : cells)
		{
			if (cell.showsOrb() && cell.orbX >= 0)
			{
				appendOrb(draw, cell);
			}
		}
		for (CompactLayout.Cell cell : cells)
		{
			if (cell.showsValue() && cell.x >= 0)
			{
				draw.add(drawCmd("text", CompactLayout.textX(cell), CompactLayout.TEXT_TOP,
					cell.text, hex(cell.color)));
			}
		}
		appendStrip(draw, cells);
		return draw;
	}

	/**
	 * One stat's orb, filled from the bottom like a vessel.
	 *
	 * The row the fill stops on is lit in proportion to how far into it the value reaches,
	 * the same as a bar, which is what saves six rows from reading as six steps. What is
	 * left above the fill is painted in the stat's own colour rather than the one it has
	 * drained to: an emptied hitpoints orb is a dim green heart, not a dim red one, so the
	 * shape and the hue still agree about whose it is.
	 */
	private void appendOrb(JsonArray draw, CompactLayout.Cell cell)
	{
		StatOrb orb = cell.orb;
		Color lit = cell.color == null ? Color.WHITE : cell.color;
		Color track = cell.identity == null ? lit : cell.identity;
		String empty = hex(brighten(track, TRACK_LEVEL));
		double level = Math.max(0, Math.min(100, cell.percent)) / 100.0 * StatOrb.HEIGHT;

		for (int y = 0; y < StatOrb.HEIGHT; y++)
		{
			// Rows fill from the bottom up, so the last row is the first to light.
			int below = StatOrb.HEIGHT - 1 - y;
			String color;
			if (level >= below + 1)
			{
				color = hex(lit);
			}
			else if (level > below)
			{
				color = hex(brighten(lit, Math.max(TRACK_LEVEL, level - below)));
			}
			else
			{
				color = empty;
			}
			for (int[] run : orb.runs(y))
			{
				draw.add(drawCmd("rectFill", cell.orbX + run[0], StatOrb.TOP + y, run[1], 1, color));
			}
		}
	}

	private JsonArray stripDraw(List<CompactLayout.Cell> cells)
	{
		JsonArray draw = new JsonArray();
		appendStrip(draw, cells);
		return draw;
	}

	private void appendStrip(JsonArray draw, List<CompactLayout.Cell> cells)
	{
		for (CompactLayout.Cell cell : cells)
		{
			if (cell.showsBar() && cell.stripX >= 0)
			{
				appendStripSegment(draw, cell);
			}
		}
	}

	/**
	 * One stat's share of the bottom row. The pixel the fill stops on is lit in proportion
	 * to how far into it the value reaches, so the bar answers a change of a percent or two
	 * instead of sitting still until it has earned a whole pixel.
	 */
	private void appendStripSegment(JsonArray draw, CompactLayout.Cell cell)
	{
		int row = CompactLayout.STRIP_ROW;
		int width = cell.stripWidth;
		Color color = cell.color == null ? Color.WHITE : cell.color;
		// Tracked in the colour the stat is always known by rather than in the colour it
		// has drained to, so an empty bar still says whose it is once the fill has ramped
		// away towards red. This is the only thing left carrying that, now that a marker
		// row over the digits turned out to sit too close to them to be readable.
		Color track = cell.identity == null ? color : cell.identity;
		draw.add(drawCmd("rectFill", cell.stripX, row, width, 1, hex(brighten(track, TRACK_LEVEL))));

		// What the stat was a moment ago, left behind so a drop is visible as it happens.
		// A dim panel has too few steps left to tell the trail from the track it sits on,
		// so below that it is dropped rather than left to smear the two together.
		if (cell.ghostPercent > cell.percent && !lowLight())
		{
			int ghost = barFullPixels(cell.ghostPercent, width);
			int from = barFullPixels(cell.percent, width);
			if (ghost > from)
			{
				draw.add(drawCmd("rectFill", cell.stripX + from, row, ghost - from, 1,
					hex(brighten(color, GHOST_LEVEL))));
			}
		}

		int full = barFullPixels(cell.percent, width);
		if (full > 0)
		{
			draw.add(drawCmd("rectFill", cell.stripX, row, full, 1, hex(color)));
		}
		int partial = barPartialPercent(cell.percent, width);
		if (partial > 0 && full < width)
		{
			draw.add(drawCmd("pixel", cell.stripX + full, row, hex(brighten(color, partial / 100.0))));
		}
	}

	/**
	 * Whole pixels a 0-100 percent fills across a bar of this width.
	 */
	static int barFullPixels(int percent, int width)
	{
		if (percent <= 0 || width <= 0)
		{
			return 0;
		}
		return Math.min(width, Math.min(100, percent) * width / 100);
	}

	/**
	 * How far into the next pixel the value reaches, 0-99, which is the brightness that
	 * pixel is lit at. Anything above zero keeps at least a trace of a pixel showing.
	 */
	static int barPartialPercent(int percent, int width)
	{
		if (percent <= 0 || width <= 0)
		{
			return 0;
		}
		int remainder = (Math.min(100, percent) * width) % 100;
		if (remainder == 0)
		{
			return 0;
		}
		return Math.max(MIN_PARTIAL, remainder);
	}

	/**
	 * Text beside the activity icon, with the bottom row painted from a gradient up to the percent.
	 */
	/**
	 * The skill progress page, with whatever stats were asked for standing as columns down
	 * the right edge. The words are centred by the firmware, so the columns are paid for by
	 * shifting them left rather than by narrowing an area we do not control.
	 */
	void pushSkillProgress(List<TextFragment> fragments, int progressPercent, List<Color> gradient,
		String activityIcon, List<CompactLayout.Cell> edgeBars)
	{
		JsonObject body = baseStatsApp();
		body.addProperty("font", "small");
		body.addProperty("textCenter", true);
		body.add("scroll", scrollStatic());
		applyActivityIcon(body, activityIcon);
		body.add("text", fragmentsJson(fragments));
		int columns = edgeBars == null ? 0 : edgeDraw(edgeBars, body);
		if (columns > 0)
		{
			body.addProperty("textOffsetX", -(CompactLayout.edgeReserve(columns) / 2));
		}
		if (progressPercent >= 0)
		{
			JsonArray palette = new JsonArray();
			for (Color stop : gradient)
			{
				palette.add(hex(stop));
			}
			body.add("palette", palette);
			body.addProperty("progress", progressPercent);
			body.addProperty("progressColor", "palette");
			body.addProperty("progressTrackColor", hex(TRACK));
			body.addProperty("textInFront", true);
		}
		putStats(body);
	}

	/**
	 * One column per stat at the right edge, filling from the bottom the way the bottom
	 * strip fills from the left, and tracked in the colour the stat is known by so an
	 * empty column still says whose it is.
	 */
	private int edgeDraw(List<CompactLayout.Cell> cells, JsonObject body)
	{
		JsonArray draw = new JsonArray();
		int columns = 0;
		for (CompactLayout.Cell cell : cells)
		{
			if (!cell.showsBar() || cell.edgeX < 0)
			{
				continue;
			}
			appendEdgeBar(draw, cell);
			columns++;
		}
		if (columns > 0)
		{
			body.add("draw", draw);
		}
		return columns;
	}

	private void appendEdgeBar(JsonArray draw, CompactLayout.Cell cell)
	{
		int height = CompactLayout.EDGE_HEIGHT;
		int top = CompactLayout.EDGE_TOP;
		Color color = cell.color == null ? Color.WHITE : cell.color;
		Color track = cell.identity == null ? color : cell.identity;
		draw.add(drawCmd("rectFill", cell.edgeX, top, 1, height, hex(brighten(track, TRACK_LEVEL))));

		int full = barFullPixels(cell.percent, height);
		if (full > 0)
		{
			draw.add(drawCmd("rectFill", cell.edgeX, top + height - full, 1, full, hex(color)));
		}
		int partial = barPartialPercent(cell.percent, height);
		if (partial > 0 && full < height)
		{
			draw.add(drawCmd("pixel", cell.edgeX, top + height - full - 1,
				hex(brighten(color, partial / 100.0))));
		}
	}

	private JsonArray fragmentsJson(List<TextFragment> fragments)
	{
		JsonArray text = new JsonArray();
		for (TextFragment fragment : fragments)
		{
			JsonObject part = new JsonObject();
			part.addProperty("text", fragment.getText());
			part.addProperty("color", hex(fragment.getColor()));
			text.add(part);
		}
		return text;
	}

	void clearStats()
	{
		lastStatsBody.set(null);
		lastStatsSentMs.set(0L);
		enqueue("DELETE", "/api/v1/apps/" + APP_STATS, null, null);
	}

	void clearAll()
	{
		clearCache();
		restoreBrightness();
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_AFK, null, null);
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_LOW_HP, null, null);
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_LOW_PRAY, null, null);
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_SPEC_READY, null, null);
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_FORESTRY, null, null);
		enqueue("DELETE", "/api/v1/notifications/" + NOTIF_XP_DROP, null, null);
		enqueue("DELETE", "/api/v1/apps/" + APP_STATS, null, null);
		restoreLoop();
	}

	/**
	 * Put the rotation back the way it was before the stats app took it over.
	 * Nothing is sent if the plugin never changed it.
	 */
	private void restoreLoop()
	{
		loopSnapshotTried.set(false);
		if (!loopChanged.getAndSet(false))
		{
			return;
		}
		AppLoop saved = savedLoop.getAndSet(null);
		if (saved == null || saved.order.isEmpty())
		{
			restoreBuiltinLoop();
			return;
		}
		enqueue("PUT", "/api/v1/apps/order", saved.toJson().toString(), null);
	}

	private void restoreBuiltinLoop()
	{
		JsonObject body = new JsonObject();
		JsonArray order = new JsonArray();
		order.add("Time");
		order.add("Date");
		order.add("Temperature");
		order.add("Humidity");
		order.add("Battery");
		body.add("order", order);
		body.add("disabled", new JsonArray());
		enqueue("PUT", "/api/v1/apps/order", body.toString(), null);
	}

	private void putStats(JsonObject body)
	{
		body.addProperty("durationMs", 60_000);
		String json = body.toString();
		long now = System.currentTimeMillis();
		Long lastSent = lastStatsSentMs.get();
		boolean identical = json.equals(lastStatsBody.get());
		boolean stale = lastSent == null || now - lastSent >= STATS_REFRESH_MS;
		if (identical && !stale)
		{
			return;
		}

		lastStatsBody.set(json);
		lastStatsSentMs.set(now);
		enqueue("PUT", "/api/v1/apps/pushed/" + APP_STATS, json, ok ->
		{
			if (!ok)
			{
				lastStatsBody.set(null);
				lastStatsSentMs.set(0L);
				return;
			}
			ensureStatsLoop();
			activateStats();
		});
	}

	/**
	 * Holds the panel where the config asks, if it asks at all.
	 *
	 * The clock's light sensor takes a dark room a long way down and has no floor under it,
	 * so the dimmer half of a page stops being legible once the lights go out. What the
	 * clock was set to is read once and put back on the way out, the same as the rotation.
	 */
	void applyBrightness()
	{
		readPanelState();
		int floor = Math.max(0, Math.min(255, config.minBrightness()));
		int wanted = Math.max(0, Math.min(255, config.brightness()));

		// Zero is the clock's own business, which is the default and what the minimum
		// below exists to put a floor under.
		if (wanted <= 0)
		{
			holdFloor(floor);
			return;
		}

		int level = Math.min(255, Math.max(MIN_FIXED_BRIGHTNESS, Math.max(wanted, floor)));
		panelBrightness.set(level);
		pin(level);
	}

	/**
	 * Steps in only when the clock has taken itself under the floor.
	 *
	 * Under about 17 the panel has so few steps of colour left that hues collapse into one
	 * another and the faintest parts of a page are not drawn at all, and the firmware has no
	 * floor of its own under its light sensor. If the sensor is what took it down there, the
	 * room brightening again is what hands the clock back its own brightness; if someone set
	 * it there by hand, holding the floor is the whole point and it is held.
	 */
	private void holdFloor(int floor)
	{
		if (floor <= 0)
		{
			restoreBrightness();
			holdingFloor.set(false);
			return;
		}

		if (holdingFloor.get())
		{
			Brightness saved = savedBrightness.get();
			boolean fromSensor = saved != null && saved.automatic;
			if (shouldRelease(fromSensor, lightLevel.get(), releaseLight.get()))
			{
				restoreBrightness();
			}
			return;
		}

		if (!shouldHoldFloor(panelBrightness.get(), floor))
		{
			// Also hands back a level pinned while the mode was Fixed, so switching back
			// to the clock's own brightness does not leave it stuck where we put it.
			restoreBrightness();
			return;
		}
		releaseLight.set(Math.max(0, lightLevel.get()) + LIGHT_RELEASE_MARGIN);
		holdingFloor.set(true);
		pin(floor);
	}

	/**
	 * The clock is under the floor and something has to hold it up. A level of zero means
	 * nothing has been read back yet, which is not the same as a dark panel.
	 */
	static boolean shouldHoldFloor(int liveBrightness, int floor)
	{
		return floor > 0 && liveBrightness > 0 && liveBrightness < floor;
	}

	/**
	 * Only a panel taken down by the light sensor is handed back, and only once the room has
	 * brightened past where it was when we stepped in. A level someone chose by hand is not
	 * given back, since holding it up is the whole point of asking for a floor.
	 */
	static boolean shouldRelease(boolean fromSensor, int light, int releaseAt)
	{
		return fromSensor && light >= releaseAt;
	}

	private void pin(int level)
	{
		JsonObject wanted = new JsonObject();
		wanted.addProperty("autoBrightness", false);
		wanted.addProperty("brightness", level);
		String json = wanted.toString();
		if (json.equals(appliedBrightness.get()))
		{
			return;
		}

		if (savedBrightness.get() != null || brightnessSnapshotTried.getAndSet(true))
		{
			putBrightness(json);
			return;
		}
		send("GET", "/api/v1/settings", null, false, result ->
		{
			if (result.ok && result.body != null)
			{
				try
				{
					JsonObject settings = gson.fromJson(result.body, JsonObject.class);
					if (settings != null)
					{
						savedBrightness.compareAndSet(null, parseBrightness(settings));
					}
				}
				catch (JsonParseException ex)
				{
					log.debug("Could not read the clock's settings", ex);
				}
			}
			putBrightness(json);
		});
	}

	/**
	 * What the panel is actually running at, and what the clock makes of the room.
	 *
	 * This comes from the device rather than the settings, because the settings only hold
	 * what someone asked for: with the light sensor driving, the level that matters is the
	 * one the clock arrived at. The reading of the room survives the sensor being switched
	 * off, which is what lets the floor be handed back when the lights come on.
	 */
	private void readPanelState()
	{
		long now = System.currentTimeMillis();
		long last = brightnessReadMs.get();
		if (now - last < BRIGHTNESS_POLL_MS || !brightnessReadMs.compareAndSet(last, now))
		{
			return;
		}
		send("GET", "/api/v1/device", null, false, result ->
		{
			if (!result.ok || result.body == null)
			{
				return;
			}
			try
			{
				JsonObject device = gson.fromJson(result.body, JsonObject.class);
				if (device == null)
				{
					return;
				}
				JsonElement level = device.get("brightness");
				if (level != null && level.isJsonPrimitive())
				{
					panelBrightness.set(Math.max(1, Math.min(255, level.getAsInt())));
				}
				JsonElement light = device.get("lightLevel");
				if (light != null && light.isJsonPrimitive())
				{
					lightLevel.set(light.getAsInt());
				}
			}
			catch (JsonParseException ex)
			{
				log.debug("Could not read the clock's state", ex);
			}
		});
	}

	private void putBrightness(String json)
	{
		appliedBrightness.set(json);
		enqueue("PATCH", "/api/v1/settings", json, ok ->
		{
			if (!ok)
			{
				// Forgotten, so the next refresh tries again and the clock is not put
				// back to a setting it never left.
				appliedBrightness.set(null);
			}
		});
	}

	/**
	 * Puts the clock's own brightness back. Nothing is sent if we never changed it.
	 */
	private void restoreBrightness()
	{
		brightnessSnapshotTried.set(false);
		holdingFloor.set(false);
		releaseLight.set(Integer.MAX_VALUE);
		if (appliedBrightness.getAndSet(null) == null)
		{
			return;
		}
		Brightness saved = savedBrightness.getAndSet(null);
		if (saved == null)
		{
			return;
		}
		enqueue("PATCH", "/api/v1/settings", saved.toJson().toString(), null);
	}

	static Brightness parseBrightness(JsonObject settings)
	{
		JsonElement auto = settings.get("autoBrightness");
		JsonElement level = settings.get("brightness");
		return new Brightness(
			auto != null && auto.isJsonPrimitive() && auto.getAsBoolean(),
			level != null && level.isJsonPrimitive() ? level.getAsInt() : 120);
	}

	private void ensureStatsLoop()
	{
		if (Boolean.TRUE.equals(loopConfigured.get()))
		{
			return;
		}
		loopConfigured.set(true);

		if (savedLoop.get() != null || loopSnapshotTried.getAndSet(true))
		{
			putStatsLoop();
			return;
		}
		send("GET", "/api/v1/apps", null, false, result ->
		{
			if (result.ok && result.body != null)
			{
				try
				{
					JsonArray apps = gson.fromJson(result.body, JsonArray.class);
					if (apps != null)
					{
						savedLoop.compareAndSet(null, parseAppLoop(apps));
					}
				}
				catch (JsonParseException ex)
				{
					log.debug("Could not read the clock's app list", ex);
				}
			}
			putStatsLoop();
		});
	}

	private void putStatsLoop()
	{
		// Keep Time as a fallback so the panel never goes blank if osrs is removed.
		JsonObject body = new JsonObject();
		JsonArray order = new JsonArray();
		order.add(APP_STATS);
		order.add("Time");
		body.add("order", order);
		body.add("disabled", new JsonArray());

		loopChanged.set(true);
		enqueue("PUT", "/api/v1/apps/order", body.toString(), null);
	}

	/**
	 * The rotation from GET /api/v1/apps: apps with a slot in slot order, plus the switched-off ones.
	 * The stats app itself is left out, since it is deleted before the rotation is restored.
	 */
	static AppLoop parseAppLoop(JsonArray apps)
	{
		List<JsonObject> slotted = new ArrayList<>();
		List<String> disabled = new ArrayList<>();
		for (JsonElement element : apps)
		{
			if (!element.isJsonObject())
			{
				continue;
			}
			JsonObject app = element.getAsJsonObject();
			String name = stringOrNull(app, "name");
			if (name == null || APP_STATS.equals(name))
			{
				continue;
			}
			if (app.has("enabled") && !app.get("enabled").isJsonNull() && !app.get("enabled").getAsBoolean())
			{
				disabled.add(name);
			}
			else if (app.has("slot") && app.get("slot").isJsonPrimitive())
			{
				slotted.add(app);
			}
		}
		slotted.sort(Comparator.comparingInt(app -> app.get("slot").getAsInt()));
		List<String> order = new ArrayList<>();
		for (JsonObject app : slotted)
		{
			order.add(app.get("name").getAsString());
		}
		return new AppLoop(order, disabled);
	}

	private static String stringOrNull(JsonObject object, String key)
	{
		JsonElement value = object.get(key);
		return value == null || !value.isJsonPrimitive() ? null : value.getAsString();
	}

	private void activateStats()
	{
		JsonObject body = new JsonObject();
		body.addProperty("name", APP_STATS);
		body.addProperty("fast", true);
		enqueue("PUT", "/api/v1/apps/active", body.toString(), null);
	}

	private void applyActivityIcon(JsonObject body, String activityIcon)
	{
		if (activityIcon == null || activityIcon.isEmpty())
		{
			return;
		}
		body.addProperty("icon", pulseIcon(activityIcon));
		body.addProperty("iconMode", "fixed");
	}

	private JsonObject baseStatsApp()
	{
		JsonObject body = new JsonObject();
		body.addProperty("backgroundColor", "#000000");
		body.addProperty("textCase", "asTyped");
		body.addProperty("lifetimeMs", 0);
		return body;
	}

	private static JsonObject scrollStatic()
	{
		JsonObject scroll = new JsonObject();
		scroll.addProperty("mode", "static");
		return scroll;
	}

	private void enqueue(String method, String path, String jsonBody, Consumer<Boolean> done)
	{
		send(method, path, jsonBody, false, done == null ? null : result -> done.accept(result.ok));
	}

	/**
	 * The clock counts as reachable whenever it answers, even with a 404 for a notification
	 * that already expired. Only no answer at all, or a rejected login, counts as unreachable.
	 * Background requests report a change in the game chat; a test reports its own result.
	 */
	private void send(String method, String path, String jsonBody, boolean test, Consumer<Result> done)
	{
		String base = baseUrl();
		if (base == null)
		{
			log.debug("AWTRIX request skipped, no clock address: {} {}", method, path);
			status("No clock address set.");
			if (done != null)
			{
				done.accept(Result.failed("no clock address"));
			}
			return;
		}

		Request.Builder builder = new Request.Builder().url(base + path);
		String username = config.username() == null ? "" : config.username().trim();
		String password = config.password() == null ? "" : config.password();
		if (!username.isEmpty())
		{
			builder.header("Authorization", Credentials.basic(username, password));
		}

		if (jsonBody != null)
		{
			builder.header("Content-Type", "application/json");
			builder.method(method, RequestBody.create(JSON, jsonBody));
		}
		else
		{
			builder.method(method, null);
		}

		httpClient.newCall(builder.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("AWTRIX request failed: {} {}", method, path, e);
				finish(Result.failed(describe(e)));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Result result;
				try (Response ignored = response)
				{
					int code = response.code();
					if (response.isSuccessful())
					{
						String body = null;
						if ("GET".equals(method) && response.body() != null)
						{
							body = response.body().string();
						}
						result = Result.ok(body);
					}
					else
					{
						log.debug("AWTRIX {} {} -> {}", method, path, code);
						result = code == 401 || code == 403
							? Result.failed("the clock rejected the login (HTTP " + code + "), check the username and password")
							: Result.answered("HTTP " + code);
					}
				}
				catch (IOException ex)
				{
					log.debug("AWTRIX response failed: {} {}", method, path, ex);
					result = Result.failed(describe(ex));
				}
				finish(result);
			}

			private void finish(Result result)
			{
				Boolean before = reachable.getAndSet(result.reachable);
				// The status line always says where things stand; the chat messages are
				// the opt-in on top of it, so a test does not overwrite its own answer.
				if (!test && (before == null || before != result.reachable))
				{
					status(result.reachable ? "Connected." : "No answer: " + result.problem + ".");
				}
				boolean announce = !test && config.connectionMessages();
				if (announce && before != null && before != result.reachable)
				{
					messages.accept(result.reachable
						? "Connected to the clock again."
						: "Lost the clock: " + result.problem + ".");
				}
				else if (announce && before == null && !result.reachable)
				{
					messages.accept("Couldn't reach the clock: " + result.problem + ".");
				}
				if (done != null)
				{
					done.accept(result);
				}
			}
		});
	}

	static String describe(IOException e)
	{
		if (e instanceof UnknownHostException)
		{
			return "unknown host, check the address";
		}
		if (e instanceof SocketTimeoutException || e instanceof ConnectException || e instanceof NoRouteToHostException)
		{
			return "no answer, check the address and that the clock is on the same network";
		}
		// OkHttp's messages carry the host and port, which should not end up in the chat log.
		return "the connection failed (" + e.getClass().getSimpleName() + ")";
	}

	private String baseUrl()
	{
		String host = config.host() == null ? "" : config.host().trim();
		if (host.isEmpty())
		{
			return null;
		}
		if (!host.startsWith("http://") && !host.startsWith("https://"))
		{
			host = "http://" + host;
		}
		while (host.endsWith("/"))
		{
			host = host.substring(0, host.length() - 1);
		}
		return host;
	}

	static String toHex(Color color)
	{
		return String.format("#%02X%02X%02X", color.getRed(), color.getGreen(), color.getBlue());
	}

	static String truncate(String text, int maxChars)
	{
		if (text == null || text.isEmpty())
		{
			return "AFK";
		}
		String trimmed = text.trim();
		if (trimmed.length() <= maxChars)
		{
			return trimmed;
		}
		return trimmed.substring(0, maxChars);
	}

	static int percentOf(int current, int max)
	{
		if (max <= 0)
		{
			return 0;
		}
		return Math.max(0, Math.min(100, (int) ((current * 100L) / max)));
	}

	@Value
	static class TextFragment
	{
		String text;
		Color color;
	}

	static final class Brightness
	{
		final boolean automatic;
		final int level;

		Brightness(boolean automatic, int level)
		{
			this.automatic = automatic;
			this.level = level;
		}

		JsonObject toJson()
		{
			JsonObject body = new JsonObject();
			body.addProperty("autoBrightness", automatic);
			body.addProperty("brightness", level);
			return body;
		}
	}

	static final class AppLoop
	{
		final List<String> order;
		final List<String> disabled;

		AppLoop(List<String> order, List<String> disabled)
		{
			this.order = order;
			this.disabled = disabled;
		}

		JsonObject toJson()
		{
			JsonObject body = new JsonObject();
			JsonArray orderJson = new JsonArray();
			order.forEach(orderJson::add);
			JsonArray disabledJson = new JsonArray();
			disabled.forEach(disabledJson::add);
			body.add("order", orderJson);
			body.add("disabled", disabledJson);
			return body;
		}
	}

	private static final class Result
	{
		final boolean ok;
		final boolean reachable;
		final String problem;
		final String body;

		private Result(boolean ok, boolean reachable, String problem, String body)
		{
			this.ok = ok;
			this.reachable = reachable;
			this.problem = problem;
			this.body = body;
		}

		static Result ok(String body)
		{
			return new Result(true, true, null, body);
		}

		static Result answered(String problem)
		{
			return new Result(false, true, problem, null);
		}

		static Result failed(String problem)
		{
			return new Result(false, false, problem, null);
		}
	}
}

package com.ulanzi.osrs;

import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.VarbitID;

/**
 * Maps the selected attack style to a melee, ranged, or magic icon.
 * Style names come from the same weapon structs the client uses.
 */
final class CombatStyles
{
	private CombatStyles()
	{
	}

	static SkillActivity current(Client client)
	{
		int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		int styleIndex = client.getVarpValue(VarPlayer.ATTACK_STYLE);
		int castingMode = client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		return activityFor(styleNames(client, weaponType), styleIndex, castingMode);
	}

	static SkillActivity activityFor(String[] styleNames, int styleIndex, int castingMode)
	{
		if (styleNames == null || styleNames.length == 0 || styleIndex < 0)
		{
			return null;
		}
		// Staff defensive autocast is the style after the spell slot.
		if (styleIndex == 4)
		{
			styleIndex += Math.max(0, castingMode);
		}
		if (styleIndex >= styleNames.length)
		{
			return null;
		}
		SkillActivity selected = activityForStyleName(styleNames[styleIndex]);
		if (selected == SkillActivity.MELEE && rangedAccurate(styleNames, styleNames[styleIndex]))
		{
			return SkillActivity.RANGED;
		}
		return selected;
	}

	/**
	 * Bows list Accurate next to Ranging and Longrange. Staves list Accurate next to Aggressive.
	 */
	private static boolean rangedAccurate(String[] styleNames, String selected)
	{
		if (selected == null || !"ACCURATE".equals(normalize(selected)))
		{
			return false;
		}
		boolean ranged = false;
		boolean otherMelee = false;
		for (String name : styleNames)
		{
			SkillActivity activity = activityForStyleName(name);
			if (activity == SkillActivity.RANGED)
			{
				ranged = true;
			}
			else if (activity == SkillActivity.MELEE && name != null && !"ACCURATE".equals(normalize(name)))
			{
				otherMelee = true;
			}
		}
		return ranged && !otherMelee;
	}

	private static String normalize(String name)
	{
		return name.toUpperCase(Locale.ENGLISH).replace(' ', '_');
	}

	static SkillActivity activityForStyleName(String name)
	{
		if (name == null || name.isEmpty())
		{
			return null;
		}
		switch (normalize(name))
		{
			case "RANGING":
			case "LONGRANGE":
				return SkillActivity.RANGED;
			case "CASTING":
			case "DEFENSIVE_CASTING":
				return SkillActivity.MAGIC;
			case "ACCURATE":
			case "AGGRESSIVE":
			case "DEFENSIVE":
			case "CONTROLLED":
				return SkillActivity.MELEE;
			default:
				return null;
		}
	}

	private static String[] styleNames(Client client, int weaponType)
	{
		EnumComposition categories = client.getEnum(EnumID.WEAPON_STYLES);
		if (categories == null)
		{
			return fallbackStyles(weaponType);
		}
		int styleEnumId = categories.getIntValue(weaponType);
		if (styleEnumId == -1)
		{
			return fallbackStyles(weaponType);
		}
		EnumComposition styles = client.getEnum(styleEnumId);
		if (styles == null || styles.getIntVals() == null)
		{
			return fallbackStyles(weaponType);
		}

		int[] structs = styles.getIntVals();
		String[] names = new String[structs.length];
		for (int i = 0; i < structs.length; i++)
		{
			StructComposition struct = client.getStructComposition(structs[i]);
			if (struct == null)
			{
				continue;
			}
			String attackStyleName = struct.getStringValue(ParamID.ATTACK_STYLE_NAME);
			if (attackStyleName == null || attackStyleName.equalsIgnoreCase("Other"))
			{
				continue;
			}
			if (i == 5 && attackStyleName.equalsIgnoreCase("Defensive"))
			{
				names[i] = "Defensive Casting";
				continue;
			}
			names[i] = attackStyleName;
		}
		return names;
	}

	private static String[] fallbackStyles(int weaponType)
	{
		if (weaponType == 22)
		{
			return new String[] {"Accurate", "Aggressive", null, "Defensive", "Casting", "Defensive Casting"};
		}
		if (weaponType == 30)
		{
			return new String[] {"Accurate", "Aggressive", "Aggressive", "Defensive"};
		}
		return new String[0];
	}
}

package com.ulanzi.osrs;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * Where everything sits on the 32x8 panel in the compact layout.
 *
 * Rows 1-5 carry the values, each in a slot wide enough for the largest number that stat
 * can reach and right aligned inside it, so a digit appearing or disappearing changes that
 * number in place instead of sliding the whole line sideways. Rows 0 and 6 are left clear
 * so nothing crowds them. Row 7 is a strip of bars sharing the full width, each one tracked
 * in the colour its stat is always known by, so an empty bar still says whose it is after
 * the fill has ramped away towards red.
 *
 * Bars living on their own row is what makes the line fit: a value demoted to a bar gives
 * up its whole slot and costs nothing horizontally, where the old right-edge columns took
 * 2px off the text no matter what.
 *
 * A {@link StatOrb} stands at either end of whatever room is left, the left one first and
 * the right one hard against the panel edge. They cost the values six columns apiece, which
 * is most of a three digit slot, so switching them on is what pushes run energy and special
 * attack down onto the strip. The strip itself is not shortened: the orbs stop at row 5,
 * and bars are free to run underneath them.
 */
final class CompactLayout
{
	static final int PANEL_WIDTH = 32;
	static final int ICON_WIDTH = 8;
	/** The small font advances 4px per character, the last column of which is blank. */
	static final int CHAR_WIDTH = 4;
	/**
	 * The top of the glyph, not its baseline: the draw list places text from here down,
	 * which is the opposite of what the scripting API's text() does.
	 *
	 * Five pixel digits from row 1 leave row 0 clear above them and row 6 clear below,
	 * which is what makes them readable. There is no room for anything else up here: a
	 * marker row, a blank, the digits, a blank and the strip is nine rows on a panel with
	 * eight, and a marker sitting straight on top of a number merges into it.
	 */
	static final int TEXT_TOP = 1;
	/** The bar strip, and for the focus layout the only row the large font leaves free. */
	static final int STRIP_ROW = 7;
	/**
	 * The skill progress page keeps its stats as columns down the right edge instead of a
	 * strip: the bottom row there is already the bar toward the next level. Each column is
	 * a pixel wide with a pixel between, and they fill from the bottom the way the strip
	 * fills from the left.
	 */
	static final int EDGE_TOP = 0;
	static final int EDGE_HEIGHT = 7;
	/** Two blank columns between values: the slot's own trailing column, and this. */
	private static final int GAP = 1;
	/** A blank column between an orb and the values, on top of the slot's own. */
	private static final int ORB_GAP = 1;

	private CompactLayout()
	{
	}

	/**
	 * One stat on the panel, or a label with no stat behind it.
	 *
	 * The style is settled by {@link #fit}, and the pixel fields by {@link #place}.
	 */
	static final class Cell
	{
		final StatKind kind;
		StatStyle style;
		final String text;
		final int digits;
		final int percent;
		/** A higher reading still fading out behind this one, or -1 for none. */
		final int ghostPercent;
		final Color color;
		final Color identity;
		/** The glyph this stat fills at the edge of the page, or null if it has none. */
		final StatOrb orb;

		int x = -1;
		int width;
		int stripX = -1;
		int stripWidth;
		int orbX = -1;
		int edgeX = -1;

		Cell(StatKind kind, StatStyle style, String text, int digits, int percent, int ghostPercent,
			Color color, Color identity)
		{
			this(kind, style, text, digits, percent, ghostPercent, color, identity, null);
		}

		Cell(StatKind kind, StatStyle style, String text, int digits, int percent, int ghostPercent,
			Color color, Color identity, StatOrb orb)
		{
			this.kind = kind;
			this.style = style;
			this.text = text;
			this.digits = digits;
			this.percent = percent;
			this.ghostPercent = ghostPercent;
			this.color = color;
			this.identity = identity;
			this.orb = orb;
		}

		/** A label has no stat behind it, so it can never be demoted to a bar. */
		static Cell label(String text, Color color)
		{
			return new Cell(null, StatStyle.VALUE, text, text.length(), -1, -1, color, null);
		}

		boolean showsValue()
		{
			return style.showsValue() && text != null && !text.isEmpty();
		}

		boolean showsBar()
		{
			return style.showsBar() && percent >= 0;
		}

		/**
		 * An orb is drawn whatever style the stat is in: it is the reading itself, not a
		 * fallback for a value that would not fit. It does need a reading to draw.
		 */
		boolean showsOrb()
		{
			return orb != null && percent >= 0;
		}
	}

	/**
	 * Room for the values: the panel, less the activity icon, less whichever orbs are up.
	 */
	static int available(List<Cell> cells, boolean icon)
	{
		return PANEL_WIDTH - (icon ? ICON_WIDTH : 0) - orbReserve(cells);
	}

	private static Cell orb(List<Cell> cells, boolean rightHand)
	{
		for (Cell cell : cells)
		{
			if (cell.showsOrb() && cell.orb.isRightHand() == rightHand)
			{
				return cell;
			}
		}
		return null;
	}

	/**
	 * What the orbs take off the line. Each side is counted on its own, so one orb alone
	 * does not cost the values the other one's columns as well.
	 */
	private static int orbReserve(List<Cell> cells)
	{
		int reserve = 0;
		if (orb(cells, false) != null)
		{
			reserve += StatOrb.WIDTH + ORB_GAP;
		}
		if (orb(cells, true) != null)
		{
			reserve += StatOrb.WIDTH + ORB_GAP;
		}
		return reserve;
	}

	/**
	 * Width of the values in lit pixels. Each slot ends in a blank column, so the one
	 * after the last value is not part of the line.
	 */
	static int lineWidth(List<Cell> cells)
	{
		int slots = 0;
		int width = 0;
		for (Cell cell : cells)
		{
			if (!cell.showsValue())
			{
				continue;
			}
			width += cell.digits * CHAR_WIDTH;
			slots++;
		}
		if (slots == 0)
		{
			return 0;
		}
		return width + (slots - 1) * GAP - 1;
	}

	static boolean fits(List<Cell> cells, boolean icon)
	{
		return lineWidth(cells) <= available(cells, icon);
	}

	/**
	 * Turns values into bars until the line fits, giving up the least wanted stat first.
	 * Whichever stat {@code keep} names goes last, so the one you chose is the one that
	 * survives a narrow panel. A bar is not a loss the way it used to be: the stat keeps
	 * a full share of the bottom strip either way.
	 */
	static void fit(List<Cell> cells, boolean icon, StatKind keep)
	{
		for (int index : demotionOrder(cells, keep))
		{
			if (fits(cells, icon))
			{
				return;
			}
			cells.get(index).style = StatStyle.BAR;
		}
	}

	/**
	 * Rightmost stat first, so the line gives up what is furthest from the eye, with the
	 * kept stat held back to the end. Labels are not in the order: they have no bar to
	 * fall back to.
	 */
	private static List<Integer> demotionOrder(List<Cell> cells, StatKind keep)
	{
		List<Integer> order = new ArrayList<>();
		int kept = -1;
		for (int i = cells.size() - 1; i >= 0; i--)
		{
			Cell cell = cells.get(i);
			if (cell.kind == null || !cell.style.showsValue())
			{
				continue;
			}
			if (cell.kind == keep)
			{
				kept = i;
			}
			else
			{
				order.add(i);
			}
		}
		if (kept >= 0)
		{
			order.add(kept);
		}
		return order;
	}

	/**
	 * Settles the pixels: the values as one centred group, and the bars sharing the whole
	 * width beneath them in the same left to right order.
	 */
	static void place(List<Cell> cells, boolean icon)
	{
		int origin = icon ? ICON_WIDTH : 0;
		Cell left = orb(cells, false);
		Cell right = orb(cells, true);
		if (left != null)
		{
			left.orbX = origin;
		}
		if (right != null)
		{
			right.orbX = PANEL_WIDTH - StatOrb.WIDTH;
		}
		int textOrigin = origin + (left != null ? StatOrb.WIDTH + ORB_GAP : 0);
		placeValues(cells, textOrigin, available(cells, icon));
		// The full width, not the room the values were left: the orbs stop above the strip,
		// so shortening the bars to clear them would give away pixels for nothing.
		placeBars(cells, origin, PANEL_WIDTH - origin);
	}

	private static void placeValues(List<Cell> cells, int origin, int available)
	{
		int x = origin + Math.max(0, (available - lineWidth(cells)) / 2);
		for (Cell cell : cells)
		{
			if (!cell.showsValue())
			{
				continue;
			}
			cell.width = cell.digits * CHAR_WIDTH;
			cell.x = x;
			x += cell.width + GAP;
		}
	}

	/**
	 * Equal shares of the full width, which is what gives a bar the room to say anything:
	 * a segment squeezed in beside a number would only have a pixel or two to move across.
	 */
	private static void placeBars(List<Cell> cells, int origin, int available)
	{
		List<Cell> bars = new ArrayList<>();
		for (Cell cell : cells)
		{
			if (cell.showsBar())
			{
				bars.add(cell);
			}
		}
		for (int i = 0; i < bars.size(); i++)
		{
			int start = origin + (available * i) / bars.size();
			int end = origin + (available * (i + 1)) / bars.size();
			Cell cell = bars.get(i);
			cell.stripX = start;
			// A blank column between segments, so two that are both dark still read apart.
			cell.stripWidth = Math.max(1, end - start - (i < bars.size() - 1 ? 1 : 0));
		}
	}

	/**
	 * What the edge columns cost the text: the columns themselves, the pixel between each
	 * pair, and one clear column between the leftmost of them and the words.
	 */
	static int edgeReserve(int bars)
	{
		return bars <= 0 ? 0 : 2 * bars;
	}

	/**
	 * The columns stand against the right edge in the order they were added, so hitpoints
	 * keeps the same place on the page whether prayer is up beside it or not.
	 */
	static int placeEdge(List<Cell> cells)
	{
		List<Cell> bars = new ArrayList<>();
		for (Cell cell : cells)
		{
			if (cell.showsBar())
			{
				bars.add(cell);
			}
		}
		for (int i = 0; i < bars.size(); i++)
		{
			bars.get(i).edgeX = PANEL_WIDTH - 1 - 2 * (bars.size() - 1 - i);
		}
		return bars.size();
	}

	/**
	 * Right aligned in the slot, so the ones column of a number never moves.
	 */
	static int textX(Cell cell)
	{
		return cell.x + Math.max(0, cell.digits - cell.text.length()) * CHAR_WIDTH;
	}
}

package com.ulanzi.osrs;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * The forest that grows behind a forestry event's name.
 *
 * Stems push up from the bottom row a little after one another, so growth runs across
 * the panel rather than happening to all eight at once, and each one opens a pair of
 * leaves once it is tall enough to have earned them. Motes of anima drift up through
 * them, wandering a pixel either way so they do not rise in columns.
 *
 * Everything is drawn in the event's own colour, which is what says which event it is
 * from across a room: the name is only readable once you are close enough to read it.
 * The motes stay near white so they still read as sparks over whatever that colour is.
 */
final class ForestryAnimation
{
	static final int WIDTH = 32;
	static final int HEIGHT = 8;
	/** Fast enough for the growth to look continuous, slow enough not to flood the clock. */
	static final long FRAME_MS = 200L;

	/** One stem every four pixels, which is eight of them across the panel. */
	private static final int STEM_SPACING = 4;
	private static final int STEMS = WIDTH / STEM_SPACING;
	private static final int STEM_MAX = 6;
	/** Leaves open once the stem has this much of itself above the floor. */
	private static final int STEM_LEAVES_AT = 3;
	private static final long STEM_CYCLE_MS = 2_000L;
	private static final long STEM_STAGGER_MS = STEM_CYCLE_MS / STEMS;
	private static final double STEM_BODY_LEVEL = 0.45;
	private static final double STEM_LEAF_LEVEL = 0.75;

	private static final int MOTES = 6;
	private static final int MOTE_SPACING = 5;
	/** One pixel of rise per step. */
	private static final long MOTE_STEP_MS = 140L;
	private static final int[] MOTE_DRIFT = {0, 1, 1, 0, -1, -1, 0, 1};
	/** How far a mote is washed out towards white. Not all the way: the name is white. */
	private static final double MOTE_PALENESS = 0.6;

	private ForestryAnimation()
	{
	}

	/**
	 * One lit pixel. The panel is small enough that a frame is a handful of these,
	 * which is cheaper to check than a list of draw commands.
	 */
	static final class Dot
	{
		final int x;
		final int y;
		final Color color;

		Dot(int x, int y, Color color)
		{
			this.x = x;
			this.y = y;
			this.color = color;
		}
	}

	static List<Dot> frame(ForestryEffect effect, Color color, long elapsedMs)
	{
		List<Dot> dots = new ArrayList<>();
		long elapsed = Math.max(0L, elapsedMs);
		if (effect.hasStems())
		{
			addStems(dots, color, elapsed);
		}
		if (effect.hasMotes())
		{
			addMotes(dots, color, elapsed);
		}
		return dots;
	}

	private static void addStems(List<Dot> dots, Color color, long elapsedMs)
	{
		Color body = shade(color, STEM_BODY_LEVEL);
		Color leaf = shade(color, STEM_LEAF_LEVEL);

		for (int stem = 0; stem < STEMS; stem++)
		{
			int height = stemHeight(stem, elapsedMs);
			if (height <= 0)
			{
				continue;
			}

			int x = stem * STEM_SPACING + 1;
			int tipY = HEIGHT - height;
			for (int y = HEIGHT - 1; y > tipY; y--)
			{
				dots.add(new Dot(x, y, body));
			}
			dots.add(new Dot(x, tipY, color));

			if (height >= STEM_LEAVES_AT)
			{
				dots.add(new Dot(x - 1, tipY + 1, leaf));
				dots.add(new Dot(x + 1, tipY + 1, leaf));
			}
		}
	}

	/**
	 * A stem's darker parts. Held here rather than borrowed from the clock so that a
	 * frame is a plain function of the time, with nothing behind it to stand up first.
	 * The panel's own floor is applied later, where every other drawn colour gets it.
	 */
	private static Color shade(Color color, double level)
	{
		return new Color((int) Math.round(color.getRed() * level),
			(int) Math.round(color.getGreen() * level),
			(int) Math.round(color.getBlue() * level));
	}

	/**
	 * Up for the first half of the cycle and back down for the second, so a stem grows
	 * and withers rather than snapping back to nothing when it reaches the top.
	 */
	static int stemHeight(int stem, long elapsedMs)
	{
		long phase = Math.floorMod(elapsedMs + stem * STEM_STAGGER_MS, STEM_CYCLE_MS);
		double t = phase / (double) STEM_CYCLE_MS;
		double rise = t < 0.5 ? t * 2 : (1 - t) * 2;
		return (int) Math.round(rise * STEM_MAX);
	}

	private static void addMotes(List<Dot> dots, Color color, long elapsedMs)
	{
		Color mote = pale(color);
		for (int index = 0; index < MOTES; index++)
		{
			long steps = elapsedMs / MOTE_STEP_MS + index * 3L;
			int y = HEIGHT - 1 - (int) Math.floorMod(steps, HEIGHT);
			int x = index * MOTE_SPACING + 2
				+ MOTE_DRIFT[(int) Math.floorMod(steps + index, MOTE_DRIFT.length)];
			dots.add(new Dot(x, y, mote));
		}
	}

	/**
	 * A mote is the brightest thing in the grove, but it stays in the event's hue rather
	 * than going white, so the name written over it is still the only white on the panel.
	 */
	private static Color pale(Color color)
	{
		return new Color(wash(color.getRed()), wash(color.getGreen()), wash(color.getBlue()));
	}

	private static int wash(int channel)
	{
		return (int) Math.round(channel + (255 - channel) * MOTE_PALENESS);
	}
}

package com.ulanzi.osrs;

import lombok.AllArgsConstructor;
import lombok.Getter;

@Getter
@AllArgsConstructor
public enum ForestryEffect
{
	GROVE("Growing grove"),
	SPROUT("Sprouting stems"),
	MOTES("Rising anima"),
	FLASH("Flashing text");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}

	boolean hasStems()
	{
		return this == GROVE || this == SPROUT;
	}

	boolean hasMotes()
	{
		return this == GROVE || this == MOTES;
	}

	boolean isAnimated()
	{
		return this != FLASH;
	}
}

