package com.ulanzi.osrs;

import java.util.List;

/**
 * Whose turn it is when several skills are being trained at once.
 *
 * Each one holds the panel for a whole turn and keeps it for the whole of that turn:
 * a drop landing for another skill, one joining the rotation or one falling out of it
 * no longer cuts a turn short. Turns used to be counted off the clock and handed out
 * by position in the list, so every change to what you had going reshuffled it under
 * you and two skills ended up flickering back and forth under a stream of drops.
 *
 * Turns are taken in the skills' own order and passed to whoever comes after the one
 * holding the panel, so the rotation walks evenly around everything you have going
 * and keeps its place whatever joins or drops out.
 */
final class SkillRotation
{
	private SkillActivity holder;
	private long turnEndsMs;
	private long turns;

	void reset()
	{
		holder = null;
		turnEndsMs = 0L;
		turns = 0L;
	}

	/**
	 * @param active every skill trained recently, in their own order.
	 * @param current what is happening right now, which takes the panel on its own
	 *                while nothing is sharing it.
	 * @param turnMs how long one turn lasts.
	 * @return the skill whose turn it is.
	 */
	SkillActivity turn(List<SkillActivity> active, SkillActivity current, long nowMs, long turnMs)
	{
		if (nowMs >= turnEndsMs)
		{
			startTurn(active.size() < 2 ? current : next(active, holder), nowMs, turnMs);
		}
		else if (active.size() < 2)
		{
			// Nothing to share with, so the panel follows what you are doing without
			// waiting for a turn to run out.
			holder = current;
		}
		else if (holder == null || !active.contains(holder))
		{
			// Whoever was holding it stopped being trained: the panel passes on down
			// the order rather than back to whichever skill paid last.
			startTurn(next(active, holder), nowMs, turnMs);
		}
		return holder;
	}

	/** How many turns have been handed out, which is what paces the level and rate swap. */
	long turns()
	{
		return turns;
	}

	private void startTurn(SkillActivity activity, long nowMs, long turnMs)
	{
		holder = activity;
		turnEndsMs = nowMs + turnMs;
		turns++;
	}

	/**
	 * The first skill past the one holding the panel, wrapping round at the end. Going
	 * by order rather than by index is what lets a skill join or drop out without
	 * moving anybody else's turn.
	 */
	private static SkillActivity next(List<SkillActivity> active, SkillActivity after)
	{
		if (active.isEmpty())
		{
			return null;
		}
		if (after != null)
		{
			for (SkillActivity activity : active)
			{
				if (activity.ordinal() > after.ordinal())
				{
					return activity;
				}
			}
		}
		return active.get(0);
	}

	/** Keeps the list in the skills' own order, so the rotation reads the same each lap. */
	static void insertInOrder(List<SkillActivity> active, SkillActivity activity)
	{
		if (activity == null || active.contains(activity))
		{
			return;
		}
		for (int i = 0; i < active.size(); i++)
		{
			if (active.get(i).ordinal() > activity.ordinal())
			{
				active.add(i, activity);
				return;
			}
		}
		active.add(activity);
	}
}

package com.ulanzi.osrs;

import java.awt.Color;
import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * The four orb stats, in the order they read across the panel.
 *
 * Each one keeps the colour it is always known by. That is not always the colour its value
 * is drawn in: a stat that ramps goes over towards red as it drains, so by the time it
 * matters the hue no longer says which stat it is. The identity colour is what the bar
 * tracks and the unfilled part of a drain orb are painted with, and it never changes.
 */
@Getter
@AllArgsConstructor
public enum StatKind
{
	HITPOINTS("Hitpoints", new Color(0x00_FF_00), 2, true, StatOrb.HITPOINTS),
	PRAYER("Prayer", new Color(0x4F_A3_FF), 2, false, StatOrb.PRAYER),
	ENERGY("Run energy", new Color(0xFF_D4_00), 3, true, null),
	SPEC("Special attack", new Color(0xFF_8C_00), 3, true, null);

	private final String name;
	private final Color identity;
	/** How many characters the slot holds, so a value never moves when it gains a digit. */
	private final int digits;
	/** Whether this stat's colour answers its own value, or holds still at every level. */
	private final boolean ramps;
	/** The glyph this stat fills at the edge of the compact page, or null for none. */
	private final StatOrb orb;

	@Override
	public String toString()
	{
		return name;
	}

	/**
	 * The colour this stat is drawn in at this percent.
	 *
	 * Hitpoints, run energy and special attack ramp: a glance says one of them is running
	 * out before any of the digits have been read, and red is the right word for all three.
	 * Prayer does not. Running out of prayer is not the emergency running out of hitpoints
	 * is, and blue is the only thing on the panel that says prayer at all - an amber one
	 * beside an amber hitpoints reads as two alarms where there is one.
	 */
	Color drained(int percent)
	{
		return ramps ? StatRamp.drain(identity, percent) : identity;
	}

	/**
	 * Digits for a stat that can be boosted past its usual ceiling, so a brewed-up
	 * hitpoints level still has somewhere to print its third digit.
	 */
	int digitsFor(int ceiling)
	{
		int needed = String.valueOf(Math.max(0, ceiling)).length();
		return Math.max(digits, needed);
	}
}

package com.ulanzi.osrs;

import java.util.ArrayList;
import java.util.List;

/**
 * The drain orbs that stand at the two ends of the compact page.
 *
 * A bar says how much is left; an orb says it without having to be read. The glyph is
 * filled from the bottom like a vessel, so hitpoints and prayer answer a glance from
 * across the room while the digits are still there for anyone who wants the number.
 *
 * Shape carries identity here, not colour. Hitpoints ramps away from green as it drains,
 * so by the time it matters a round orb would be an anonymous red blob: the heart and the
 * diamond stay themselves at every level, which is why they are not two circles.
 *
 * Five wide and six tall. Six rows is a sixth of the stat per row, which would be coarse
 * on its own, so the row the fill stops on is lit in proportion to how far into it the
 * value reaches, the same as the bars. Rows 0-5 leave row 6 clear above the strip.
 */
enum StatOrb
{
	HITPOINTS(false, new String[] {
		".X.X.",
		"XXXXX",
		"XXXXX",
		"XXXXX",
		".XXX.",
		"..X.."
	}),
	PRAYER(true, new String[] {
		"..X..",
		".XXX.",
		"XXXXX",
		"XXXXX",
		".XXX.",
		"..X.."
	});

	static final int WIDTH = 5;
	static final int HEIGHT = 6;
	/** The top row of an orb. Row 6 is left clear so it never touches the strip. */
	static final int TOP = 0;

	private final boolean rightHand;
	/**
	 * Each row as its lit stretches, {@code {start, length}}. Drawing a run at a time
	 * rather than a pixel at a time is what keeps two orbs down to thirteen commands.
	 */
	private final int[][][] runs;

	StatOrb(boolean rightHand, String[] rows)
	{
		if (rows.length != HEIGHT)
		{
			throw new IllegalArgumentException("Orb must be " + HEIGHT + " rows");
		}
		this.rightHand = rightHand;
		this.runs = new int[HEIGHT][][];
		for (int y = 0; y < HEIGHT; y++)
		{
			this.runs[y] = runs(rows[y]);
		}
	}

	/** True for the orb that sits against the right edge, false for the left. */
	boolean isRightHand()
	{
		return rightHand;
	}

	int[][] runs(int row)
	{
		return runs[row];
	}

	private static int[][] runs(String row)
	{
		if (row.length() != WIDTH)
		{
			throw new IllegalArgumentException("Orb row must be " + WIDTH + " pixels: " + row);
		}
		List<int[]> found = new ArrayList<>();
		int start = -1;
		for (int x = 0; x <= WIDTH; x++)
		{
			boolean lit = x < WIDTH && row.charAt(x) == 'X';
			if (lit && start < 0)
			{
				start = x;
			}
			else if (!lit && start >= 0)
			{
				found.add(new int[] {start, x - start});
				start = -1;
			}
		}
		return found.toArray(new int[0][]);
	}
}

package com.ulanzi.osrs;

import java.awt.Color;

/**
 * How a stat's colour answers its own value.
 *
 * Hitpoints used to be the only stat that changed colour, and only in three steps, while
 * prayer, run energy and special attack stayed the same shade whether they were full or
 * nearly gone. Every stat ramps now, and smoothly: a glance says something is running out
 * before any of the digits have been read.
 */
final class StatRamp
{
	/** Full colour down to here. */
	private static final int HIGH = 50;
	/** All the way over to amber by here. */
	private static final int LOW = 25;
	private static final Color AMBER = new Color(0xFF_A0_00);
	private static final Color EMPTY = new Color(0xFF_20_00);

	private StatRamp()
	{
	}

	static Color drain(Color base, int percent)
	{
		int value = Math.max(0, Math.min(100, percent));
		if (value >= HIGH)
		{
			return base;
		}
		if (value >= LOW)
		{
			return blend(AMBER, base, (value - LOW) / (double) (HIGH - LOW));
		}
		return blend(EMPTY, AMBER, value / (double) LOW);
	}

	/**
	 * {@code towards} at 1, {@code from} at 0.
	 */
	static Color blend(Color from, Color towards, double amount)
	{
		double t = Math.max(0.0, Math.min(1.0, amount));
		return new Color(
			mix(from.getRed(), towards.getRed(), t),
			mix(from.getGreen(), towards.getGreen(), t),
			mix(from.getBlue(), towards.getBlue(), t));
	}

	private static int mix(int from, int towards, double amount)
	{
		return Math.max(0, Math.min(255, (int) Math.round(from + (towards - from) * amount)));
	}
}

