package com.ulanzi.osrs;

import java.util.ArrayDeque;
import java.util.EnumMap;
import java.util.Iterator;
import net.runelite.api.Skill;

/**
 * XP per hour for each skill, either averaged over the whole session or over a
 * trailing window. A session average ignores the first drop so it is not
 * inflated by XP earned before the session began; the window counts it, because
 * there is no session length for it to distort. A break longer than
 * {@link #BREAK_MS} starts a new session.
 */
final class XpRateTracker
{
	static final long BREAK_MS = 5 * 60_000L;
	/** The longest window {@link #perHourWindow} serves. Older drops are forgotten. */
	static final long MAX_WINDOW_MS = 900_000L;
	private static final long HOUR_MS = 3_600_000L;

	private final EnumMap<Skill, Session> sessions = new EnumMap<>(Skill.class);

	void reset()
	{
		sessions.clear();
	}

	void onXp(Skill skill, int gained, long nowMs)
	{
		Session session = sessions.get(skill);
		if (session == null || nowMs - session.lastMs > BREAK_MS)
		{
			session = new Session(nowMs);
			sessions.put(skill, session);
			session.recent.addLast(new Gain(nowMs, gained));
			return;
		}
		session.gained += gained;
		session.lastMs = nowMs;
		session.recent.addLast(new Gain(nowMs, gained));
		while (nowMs - session.recent.peekFirst().atMs > MAX_WINDOW_MS)
		{
			session.recent.removeFirst();
		}
	}

	/**
	 * Averaged over the whole session: -1 until a second drop gives the session a
	 * length, and after a break.
	 */
	int perHour(Skill skill, long nowMs)
	{
		Session session = sessions.get(skill);
		if (session == null || session.gained <= 0 || nowMs - session.lastMs > BREAK_MS)
		{
			return -1;
		}
		long elapsed = Math.max(1L, nowMs - session.startMs);
		return (int) Math.min(Integer.MAX_VALUE, session.gained * HOUR_MS / elapsed);
	}

	/**
	 * Averaged over the last {@code windowMs}, always divided by the whole window
	 * rather than by however much of it has been played. The rate climbs from zero
	 * over the first window and falls back to zero once you stop, which is what
	 * makes it track what you are doing now instead of the session so far. -1
	 * before the first drop and after a break.
	 */
	int perHourWindow(Skill skill, long nowMs, long windowMs)
	{
		Session session = sessions.get(skill);
		if (session == null || nowMs - session.lastMs > BREAK_MS)
		{
			return -1;
		}
		long window = Math.max(1L, Math.min(windowMs, MAX_WINDOW_MS));
		long gained = 0L;
		// Newest first, so the walk stops at the edge of the window.
		for (Iterator<Gain> drops = session.recent.descendingIterator(); drops.hasNext(); )
		{
			Gain drop = drops.next();
			if (nowMs - drop.atMs >= window)
			{
				break;
			}
			gained += drop.xp;
		}
		return (int) Math.min(Integer.MAX_VALUE, gained * HOUR_MS / window);
	}

	/**
	 * At most four characters so the level still fits beside it: 950, 9.5k, 125k, 1.2m, 12m.
	 */
	static String format(int perHour)
	{
		if (perHour < 1_000)
		{
			return String.valueOf(Math.max(0, perHour));
		}
		if (perHour < 10_000)
		{
			return tenths(perHour / 100) + "k";
		}
		if (perHour < 1_000_000)
		{
			return (perHour / 1_000) + "k";
		}
		if (perHour < 10_000_000)
		{
			return tenths(perHour / 100_000) + "m";
		}
		return (perHour / 1_000_000) + "m";
	}

	private static String tenths(int tenths)
	{
		int whole = tenths / 10;
		int fraction = tenths % 10;
		return fraction == 0 ? String.valueOf(whole) : whole + "." + fraction;
	}

	private static final class Session
	{
		private final long startMs;
		private final ArrayDeque<Gain> recent = new ArrayDeque<>();
		private long lastMs;
		private long gained;

		private Session(long startMs)
		{
			this.startMs = startMs;
			this.lastMs = startMs;
		}
	}

	private static final class Gain
	{
		private final long atMs;
		private final int xp;

		private Gain(long atMs, int xp)
		{
			this.atMs = atMs;
			this.xp = xp;
		}
	}
}

package com.ulanzi.osrs;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class CompactLayoutTest
{
	@Test
	public void theDefaultThreeValuesFitTheBarePanel()
	{
		List<CompactLayout.Cell> cells = defaults();
		CompactLayout.fit(cells, false, StatKind.HITPOINTS);
		for (CompactLayout.Cell cell : cells)
		{
			Assert.assertEquals(cell.kind.name(), StatStyle.VALUE, cell.style);
		}
		// Two 2-digit slots and one 3-digit, a blank column between each, and the last
		// slot's own trailing column is not part of the line: 8 + 8 + 12 + 2 - 1.
		Assert.assertEquals(29, CompactLayout.lineWidth(cells));
		Assert.assertTrue(CompactLayout.fits(cells, false));
	}

	@Test
	public void anIconPushesTheRightmostValueOntoTheStrip()
	{
		List<CompactLayout.Cell> cells = defaults();
		CompactLayout.fit(cells, true, StatKind.HITPOINTS);
		Assert.assertEquals(StatStyle.VALUE, cells.get(0).style);
		Assert.assertEquals(StatStyle.VALUE, cells.get(1).style);
		Assert.assertEquals(StatStyle.BAR, cells.get(2).style);
		Assert.assertTrue(CompactLayout.fits(cells, true));
	}

	@Test
	public void theKeptStatIsTheLastToGiveUpItsDigits()
	{
		List<CompactLayout.Cell> cells = defaults();
		CompactLayout.fit(cells, true, StatKind.ENERGY);
		Assert.assertEquals(StatStyle.VALUE, cells.get(0).style);
		Assert.assertEquals(StatStyle.BAR, cells.get(1).style);
		Assert.assertEquals(StatStyle.VALUE, cells.get(2).style);
		Assert.assertTrue(CompactLayout.fits(cells, true));
	}

	@Test
	public void anAfkLabelTakesRoomFromTheValuesAndNeverFromItself()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(CompactLayout.Cell.label("AFK", Color.WHITE));
		cells.addAll(defaults());
		CompactLayout.fit(cells, true, StatKind.HITPOINTS);
		Assert.assertEquals(StatStyle.VALUE, cells.get(0).style);
		Assert.assertEquals(StatStyle.VALUE, cells.get(1).style);
		Assert.assertEquals(StatStyle.BAR, cells.get(2).style);
		Assert.assertEquals(StatStyle.BAR, cells.get(3).style);
		Assert.assertTrue(CompactLayout.fits(cells, true));
	}

	/**
	 * The point of the whole layout: a slot is sized by what the stat can reach, so the
	 * line does not move when a number loses a digit.
	 */
	@Test
	public void aValueLosingADigitMovesNothing()
	{
		List<CompactLayout.Cell> full = defaults();
		CompactLayout.place(full, false);

		List<CompactLayout.Cell> dropped = new ArrayList<>();
		dropped.add(cell(StatKind.HITPOINTS, StatStyle.VALUE, 9, 9, 99));
		dropped.add(cell(StatKind.PRAYER, StatStyle.VALUE, 7, 10, 70));
		dropped.add(cell(StatKind.ENERGY, StatStyle.VALUE, 8, 8, 100));
		CompactLayout.place(dropped, false);

		for (int i = 0; i < full.size(); i++)
		{
			Assert.assertEquals("slot " + i, full.get(i).x, dropped.get(i).x);
			Assert.assertEquals("width " + i, full.get(i).width, dropped.get(i).width);
		}
		// The ones column holds still; only the empty leading columns are given up.
		Assert.assertEquals(full.get(0).x + CompactLayout.CHAR_WIDTH, CompactLayout.textX(dropped.get(0)));
		Assert.assertEquals(full.get(2).x + 2 * CompactLayout.CHAR_WIDTH, CompactLayout.textX(dropped.get(2)));
	}

	@Test
	public void valuesAreRightAlignedInTheirSlot()
	{
		List<CompactLayout.Cell> cells = defaults();
		CompactLayout.place(cells, false);
		Assert.assertEquals(cells.get(0).x, CompactLayout.textX(cells.get(0)));
		Assert.assertEquals(cells.get(2).x, CompactLayout.textX(cells.get(2)));
	}

	@Test
	public void barsShareTheWholeWidthBesideAnIcon()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(cell(StatKind.HITPOINTS, StatStyle.BAR, 99, 100, 99));
		cells.add(cell(StatKind.PRAYER, StatStyle.BAR, 70, 70, 70));
		CompactLayout.place(cells, true);

		Assert.assertEquals(CompactLayout.ICON_WIDTH, cells.get(0).stripX);
		Assert.assertEquals(20, cells.get(1).stripX);
		// A blank column between the two, and the second runs to the panel edge.
		Assert.assertEquals(11, cells.get(0).stripWidth);
		Assert.assertEquals(12, cells.get(1).stripWidth);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH,
			cells.get(1).stripX + cells.get(1).stripWidth);
	}

	@Test
	public void aLoneBarTakesTheWholeRow()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(cell(StatKind.HITPOINTS, StatStyle.BAR, 50, 100, 99));
		CompactLayout.place(cells, false);
		Assert.assertEquals(0, cells.get(0).stripX);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH, cells.get(0).stripWidth);
	}

	/**
	 * A stat that has given up its digits still costs nothing across the line, which is
	 * what the old right-edge columns could never do.
	 */
	@Test
	public void aBarTakesNoRoomFromTheLine()
	{
		List<CompactLayout.Cell> cells = defaults();
		int before = CompactLayout.lineWidth(cells);
		cells.get(2).style = StatStyle.BAR;
		Assert.assertEquals(before - CompactLayout.CHAR_WIDTH * 3 - 1, CompactLayout.lineWidth(cells));
	}

	@Test
	public void aBoostedLevelGetsAThirdDigit()
	{
		Assert.assertEquals(2, StatKind.HITPOINTS.digitsFor(99));
		Assert.assertEquals(3, StatKind.HITPOINTS.digitsFor(117));
		Assert.assertEquals(3, StatKind.ENERGY.digitsFor(100));
		Assert.assertEquals(3, StatKind.ENERGY.digitsFor(4));
	}

	@Test
	public void orbsTakeTheTwoEndsAndPushRunEnergyOntoTheStrip()
	{
		List<CompactLayout.Cell> cells = orbed();
		CompactLayout.fit(cells, false, StatKind.HITPOINTS);
		CompactLayout.place(cells, false);

		// Six columns off each end leaves twenty, which holds the two 2-digit slots but
		// not run energy's three.
		Assert.assertEquals(20, CompactLayout.available(cells, false));
		Assert.assertEquals(StatStyle.VALUE, cells.get(0).style);
		Assert.assertEquals(StatStyle.VALUE, cells.get(1).style);
		Assert.assertEquals(StatStyle.BAR, cells.get(2).style);

		Assert.assertEquals(0, cells.get(0).orbX);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH - StatOrb.WIDTH, cells.get(1).orbX);
		Assert.assertEquals(-1, cells.get(2).orbX);
	}

	@Test
	public void theValuesSitClearOfBothOrbs()
	{
		List<CompactLayout.Cell> cells = orbed();
		CompactLayout.fit(cells, false, StatKind.HITPOINTS);
		CompactLayout.place(cells, false);

		for (CompactLayout.Cell cell : cells)
		{
			if (!cell.showsValue())
			{
				continue;
			}
			Assert.assertTrue(cell.kind.getName() + " starts at " + cell.x, cell.x >= StatOrb.WIDTH + 1);
			int right = cell.x + cell.width;
			Assert.assertTrue(cell.kind.getName() + " ends at " + right,
				right <= CompactLayout.PANEL_WIDTH - StatOrb.WIDTH - 1);
		}
	}

	@Test
	public void oneOrbCostsTheLineOnlyItsOwnSide()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(orb(StatKind.HITPOINTS, StatStyle.VALUE, 99, 100, 99));
		cells.add(cell(StatKind.PRAYER, StatStyle.VALUE, 70, 100, 70));
		CompactLayout.place(cells, false);

		Assert.assertEquals(CompactLayout.PANEL_WIDTH - StatOrb.WIDTH - 1,
			CompactLayout.available(cells, false));
		Assert.assertEquals(0, cells.get(0).orbX);
		Assert.assertEquals(-1, cells.get(1).orbX);
	}

	/**
	 * The activity icon owns the left of the panel, so the orbs stand inside whatever it
	 * leaves rather than underneath it.
	 */
	@Test
	public void theLeftOrbStandsBesideTheActivityIconRatherThanUnderIt()
	{
		List<CompactLayout.Cell> cells = orbed();
		CompactLayout.fit(cells, true, StatKind.HITPOINTS);
		CompactLayout.place(cells, true);

		Assert.assertEquals(CompactLayout.ICON_WIDTH, cells.get(0).orbX);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH - StatOrb.WIDTH, cells.get(1).orbX);
		Assert.assertEquals(12, CompactLayout.available(cells, true));
		Assert.assertTrue(CompactLayout.fits(cells, true));
	}

	/**
	 * The orbs stop above the strip, so a bar running under them loses nothing.
	 */
	@Test
	public void barsStillReachBothEdgesUnderTheOrbs()
	{
		List<CompactLayout.Cell> cells = orbed();
		CompactLayout.fit(cells, false, StatKind.HITPOINTS);
		CompactLayout.place(cells, false);

		CompactLayout.Cell energy = cells.get(2);
		Assert.assertEquals(0, energy.stripX);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH, energy.stripX + energy.stripWidth);
	}

	private static List<CompactLayout.Cell> orbed()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(orb(StatKind.HITPOINTS, StatStyle.VALUE, 99, 100, 99));
		cells.add(orb(StatKind.PRAYER, StatStyle.VALUE, 70, 100, 70));
		cells.add(cell(StatKind.ENERGY, StatStyle.VALUE, 100, 100, 100));
		return cells;
	}

	private static CompactLayout.Cell orb(StatKind kind, StatStyle style, int value, int percent, int ceiling)
	{
		return new CompactLayout.Cell(kind, style, String.valueOf(value),
			kind.digitsFor(Math.max(ceiling, value)), percent, -1, Color.WHITE, kind.getIdentity(),
			kind.getOrb());
	}

	private static List<CompactLayout.Cell> defaults()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(cell(StatKind.HITPOINTS, StatStyle.VALUE, 99, 100, 99));
		cells.add(cell(StatKind.PRAYER, StatStyle.VALUE, 70, 100, 70));
		cells.add(cell(StatKind.ENERGY, StatStyle.VALUE, 100, 100, 100));
		return cells;
	}

	/**
	 * The ceiling is the largest the stat can read, which is what sizes the slot. It does
	 * not follow the value down, which is the whole reason the line holds still.
	 */
	private static CompactLayout.Cell cell(StatKind kind, StatStyle style, int value, int percent, int ceiling)
	{
		return new CompactLayout.Cell(kind, style, String.valueOf(value),
			kind.digitsFor(Math.max(ceiling, value)), percent, -1, Color.WHITE, kind.getIdentity());
	}
}

package com.ulanzi.osrs;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import okhttp3.OkHttpClient;
import org.junit.Assert;
import org.junit.Test;

/**
 * The compact page is nothing but draw commands now, so what it is worth checking is that
 * every one of them lands on the panel, and clear of the icon when there is one.
 */
public class CompactRenderTest
{
	private static final int ICON = CompactLayout.ICON_WIDTH;
	/** AWTRIX's small font: capitals are five pixels tall. */
	private static final int CAP_HEIGHT = 5;

	@Test
	public void everyCommandStaysOnThePanelBesideAnIcon()
	{
		assertInBounds(render(page(true)), true);
	}

	@Test
	public void everyCommandStaysOnThePanelWithoutAnIcon()
	{
		assertInBounds(render(page(false)), false);
	}

	@Test
	public void everyOrbCommandStaysOnThePanelAndAboveTheStrip()
	{
		for (boolean icon : new boolean[] {false, true})
		{
			JsonArray draw = render(orbed(icon, 100, 100));
			assertInBounds(draw, icon);
			int orbRows = 0;
			for (JsonElement element : draw)
			{
				JsonArray command = element.getAsJsonArray();
				if (!"rectFill".equals(command.get(0).getAsString()))
				{
					continue;
				}
				int y = command.get(2).getAsInt();
				if (y == CompactLayout.STRIP_ROW)
				{
					continue;
				}
				orbRows++;
				// Row 6 is left clear, so an orb never touches the strip below it.
				Assert.assertTrue("orb row " + y, y >= StatOrb.TOP && y < StatOrb.TOP + StatOrb.HEIGHT);
				Assert.assertTrue("orb row " + y + " crowds the strip",
					y < CompactLayout.STRIP_ROW - 1);
			}
			// The heart's seven runs and the diamond's six.
			Assert.assertEquals(13, orbRows);
		}
	}

	/**
	 * The whole point of an orb: the same glyph, lit differently as the stat goes.
	 */
	@Test
	public void anOrbEmptiesFromTheTopAsTheStatDrains()
	{
		Assert.assertEquals(StatOrb.HEIGHT, litOrbRows(100));
		Assert.assertEquals(3, litOrbRows(50));
		Assert.assertEquals(0, litOrbRows(0));
		Assert.assertTrue(litOrbRows(83) > litOrbRows(50));
	}

	/**
	 * What is left above the fill keeps the stat's own colour rather than the one it has
	 * drained to, so an emptied hitpoints orb is a dim green heart and not a dim red one.
	 */
	@Test
	public void theEmptyPartOfAnOrbHoldsTheStatsOwnColour()
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(new CompactLayout.Cell(StatKind.HITPOINTS, StatStyle.VALUE, "5", 2, 5, -1,
			StatKind.HITPOINTS.drained(5), StatKind.HITPOINTS.getIdentity(), StatOrb.HITPOINTS));
		CompactLayout.place(cells, false);

		String track = AwtrixClient.toHex(AwtrixClient.lift(
			AwtrixClient.brighten(StatKind.HITPOINTS.getIdentity(), 0.22),
			AwtrixClient.visibleFloor(AwtrixClient.DEFAULT_BRIGHTNESS)));
		int held = 0;
		for (JsonElement element : render(cells))
		{
			JsonArray command = element.getAsJsonArray();
			if (track.equals(command.get(command.size() - 1).getAsString()))
			{
				held++;
			}
		}
		Assert.assertTrue("nothing held the identity colour", held > 0);
	}

	/** How many of an orb's six rows are lit at their full colour. */
	private static int litOrbRows(int percent)
	{
		JsonArray draw = render(orbed(false, percent, percent));
		String lit = AwtrixClient.toHex(AwtrixClient.lift(StatKind.PRAYER.getIdentity(),
			AwtrixClient.visibleFloor(AwtrixClient.DEFAULT_BRIGHTNESS)));
		java.util.Set<Integer> rows = new java.util.HashSet<>();
		for (JsonElement element : draw)
		{
			JsonArray command = element.getAsJsonArray();
			if ("rectFill".equals(command.get(0).getAsString())
				&& lit.equals(command.get(command.size() - 1).getAsString())
				&& command.get(2).getAsInt() != CompactLayout.STRIP_ROW)
			{
				rows.add(command.get(2).getAsInt());
			}
		}
		return rows.size();
	}

	/** Hitpoints and prayer with their orbs up, which is the page as it ships. */
	private static List<CompactLayout.Cell> orbed(boolean icon, int hp, int prayer)
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(new CompactLayout.Cell(StatKind.HITPOINTS, StatStyle.VALUE, "99", 2, hp, -1,
			StatKind.HITPOINTS.drained(hp), StatKind.HITPOINTS.getIdentity(), StatOrb.HITPOINTS));
		cells.add(new CompactLayout.Cell(StatKind.PRAYER, StatStyle.VALUE, "70", 2, prayer, -1,
			StatKind.PRAYER.drained(prayer), StatKind.PRAYER.getIdentity(), StatOrb.PRAYER));
		cells.add(new CompactLayout.Cell(StatKind.ENERGY, StatStyle.VALUE, "100", 3, 100, -1,
			StatKind.ENERGY.drained(100), StatKind.ENERGY.getIdentity()));
		CompactLayout.fit(cells, icon, StatKind.HITPOINTS);
		CompactLayout.place(cells, icon);
		return cells;
	}

	@Test
	public void theStripReachesBothEdges()
	{
		List<CompactLayout.Cell> cells = page(false);
		int left = CompactLayout.PANEL_WIDTH;
		int right = 0;
		for (CompactLayout.Cell cell : cells)
		{
			if (cell.showsBar())
			{
				left = Math.min(left, cell.stripX);
				right = Math.max(right, cell.stripX + cell.stripWidth);
			}
		}
		Assert.assertEquals(0, left);
		Assert.assertEquals(CompactLayout.PANEL_WIDTH, right);
	}

	@Test
	public void aLostReadingLeavesATrailAndAFullOneDoesNot()
	{
		Assert.assertTrue(hasGhostPixels(withGhost(40, 90)));
		Assert.assertFalse(hasGhostPixels(withGhost(40, -1)));
		// A trail is only ever behind the value, never ahead of it.
		Assert.assertFalse(hasGhostPixels(withGhost(90, 40)));
	}

	private boolean hasGhostPixels(List<CompactLayout.Cell> cells)
	{
		JsonArray draw = render(cells);
		Color dim = AwtrixClient.brighten(Color.WHITE, 0.5);
		String hex = AwtrixClient.toHex(dim);
		for (JsonElement element : draw)
		{
			JsonArray command = element.getAsJsonArray();
			String color = command.get(command.size() - 1).getAsString();
			if (hex.equals(color))
			{
				return true;
			}
		}
		return false;
	}

	private static List<CompactLayout.Cell> withGhost(int percent, int ghost)
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(new CompactLayout.Cell(StatKind.HITPOINTS, StatStyle.BOTH, "50", 2, percent, ghost,
			Color.WHITE, Color.WHITE));
		CompactLayout.place(cells, false);
		return cells;
	}

	/** The four stats as someone running them all would have them. */
	private static List<CompactLayout.Cell> page(boolean icon)
	{
		List<CompactLayout.Cell> cells = new ArrayList<>();
		cells.add(new CompactLayout.Cell(StatKind.HITPOINTS, StatStyle.BOTH, "99", 2, 100, -1,
			Color.GREEN, StatKind.HITPOINTS.getIdentity()));
		cells.add(new CompactLayout.Cell(StatKind.PRAYER, StatStyle.BOTH, "70", 2, 70, 85,
			Color.BLUE, StatKind.PRAYER.getIdentity()));
		cells.add(new CompactLayout.Cell(StatKind.ENERGY, StatStyle.BOTH, "100", 3, 100, -1,
			Color.YELLOW, StatKind.ENERGY.getIdentity()));
		cells.add(new CompactLayout.Cell(StatKind.SPEC, StatStyle.BAR, "50", 3, 50, -1,
			Color.ORANGE, StatKind.SPEC.getIdentity()));
		CompactLayout.fit(cells, icon, StatKind.HITPOINTS);
		CompactLayout.place(cells, icon);
		return cells;
	}

	private static void assertInBounds(JsonArray draw, boolean icon)
	{
		Assert.assertTrue("nothing was drawn", draw.size() > 0);
		int floor = icon ? ICON : 0;
		for (JsonElement element : draw)
		{
			JsonArray command = element.getAsJsonArray();
			String op = command.get(0).getAsString();
			int x = command.get(1).getAsInt();
			int y = command.get(2).getAsInt();
			Assert.assertTrue(op + " starts at " + x, x >= floor);
			Assert.assertTrue(op + " row " + y, y >= 0 && y < 8);
			if ("rectFill".equals(op))
			{
				int right = x + command.get(3).getAsInt();
				int bottom = y + command.get(4).getAsInt();
				Assert.assertTrue(op + " ends at " + right, right <= CompactLayout.PANEL_WIDTH);
				Assert.assertTrue(op + " ends on row " + bottom, bottom <= 8);
			}
			if ("text".equals(op))
			{
				// y is the top of the glyph, so five pixel capitals have to finish above
				// the strip. Getting this the wrong way up ran the digits off the panel.
				Assert.assertTrue("text top " + y, y >= 0);
				Assert.assertTrue("text bottom " + (y + CAP_HEIGHT), y + CAP_HEIGHT <= CompactLayout.STRIP_ROW);
			}
			if ("pixel".equals(op))
			{
				Assert.assertTrue(op + " at " + x, x < CompactLayout.PANEL_WIDTH);
			}
		}
	}

	private static JsonArray render(List<CompactLayout.Cell> cells)
	{
		AwtrixClient client = new AwtrixClient(new OkHttpClient(), new UlanziConfig()
		{
		}, new Gson());
		return client.compactDraw(cells);
	}
}

package com.ulanzi.osrs;

import java.awt.Color;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class ForestryTest
{
	private static final Color GREEN = new Color(0x4F, 0xE0, 0x8A);
	/** Long enough to cover a whole stem cycle and several turns of the motes. */
	private static final long RUN_MS = 12_000L;

	@Test
	public void everyFrameStaysOnThePanel()
	{
		for (ForestryEffect effect : ForestryEffect.values())
		{
			for (long elapsed = 0; elapsed < RUN_MS; elapsed += 20)
			{
				for (ForestryAnimation.Dot dot : ForestryAnimation.frame(effect, GREEN, elapsed))
				{
					Assert.assertTrue(effect + " at " + elapsed + " drew x " + dot.x,
						dot.x >= 0 && dot.x < ForestryAnimation.WIDTH);
					Assert.assertTrue(effect + " at " + elapsed + " drew y " + dot.y,
						dot.y >= 0 && dot.y < ForestryAnimation.HEIGHT);
				}
			}
		}
	}

	@Test
	public void flashingDrawsNothing()
	{
		Assert.assertTrue(ForestryAnimation.frame(ForestryEffect.FLASH, GREEN, 500L).isEmpty());
	}

	@Test
	public void bothPartsOfTheGroveAreThere()
	{
		// Stems are drawn in the event's colour and motes are not, which is how the two
		// halves of the grove are told apart once they are in the same list.
		List<ForestryAnimation.Dot> grove = ForestryAnimation.frame(ForestryEffect.GROVE, GREEN, 700L);
		Assert.assertTrue(grove.size()
			> ForestryAnimation.frame(ForestryEffect.SPROUT, GREEN, 700L).size());
		Assert.assertTrue(grove.size()
			> ForestryAnimation.frame(ForestryEffect.MOTES, GREEN, 700L).size());
	}

	@Test
	public void aStemGrowsAndWithersRatherThanSnappingBack()
	{
		int start = ForestryAnimation.stemHeight(0, 0L);
		int middle = ForestryAnimation.stemHeight(0, 1_000L);
		int quarter = ForestryAnimation.stemHeight(0, 500L);
		int threeQuarters = ForestryAnimation.stemHeight(0, 1_500L);

		Assert.assertEquals(0, start);
		Assert.assertTrue("grows", quarter > start);
		Assert.assertTrue("peaks in the middle", middle > quarter);
		Assert.assertEquals("withers back the way it came", quarter, threeQuarters);
	}

	@Test
	public void stemsDoNotAllGrowAtOnce()
	{
		Set<Integer> heights = new HashSet<>();
		for (int stem = 0; stem < ForestryAnimation.WIDTH / 4; stem++)
		{
			heights.add(ForestryAnimation.stemHeight(stem, 0L));
		}
		Assert.assertTrue("stems are staggered across the panel", heights.size() > 1);
	}

	@Test
	public void noIdBelongsToTwoEvents()
	{
		Set<Integer> npcs = new HashSet<>();
		Set<Integer> objects = new HashSet<>();
		for (ForestryEvent event : ForestryEvent.values())
		{
			int seen = 0;
			for (int npc = 0; npc < 65_536; npc++)
			{
				if (ForestryEvent.fromNpc(npc) == event)
				{
					Assert.assertTrue("npc " + npc + " twice", npcs.add(npc));
					seen++;
				}
			}
			for (int object = 0; object < 65_536; object++)
			{
				if (ForestryEvent.fromObject(object) == event)
				{
					Assert.assertTrue("object " + object + " twice", objects.add(object));
					seen++;
				}
			}
			Assert.assertTrue(event + " has nothing to recognise it by", seen > 0);
		}
	}

	@Test
	public void everyLabelFitsAcrossThePanel()
	{
		for (ForestryEvent event : ForestryEvent.values())
		{
