		ForestryTracker tracker = new ForestryTracker();
		tracker.onSpawn(ForestryEvent.RISING_ROOTS, 1L, 1_000L);
		tracker.onDespawn(ForestryEvent.RISING_ROOTS, 1L, 2_000L);
